package chtypes

// setup_cases_test.go — the process setup's shared public-API cases
// (tests/fixtures/abi-v1/setup-cases.json, generated by
// scripts/abi-v1/emit/setup_cases.py and read by all four bindings), run
// through the public API over a fresh copy of a stub library. Without
// CHTYPES_ABI1_STUBS it skips LOUDLY by name.

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"testing"
)

type setupCaseExpect struct {
	OK     bool    `json:"ok"`
	Class  string  `json:"class"`
	Status string  `json:"status"`
	ChCode *int32  `json:"ch_code"`
	ChName *string `json:"ch_name"`
}

type setupCaseStep struct {
	Op       string          `json:"op"`
	Timezone string          `json:"timezone"`
	Expect   setupCaseExpect `json:"expect"`
}

type setupCase struct {
	ID      string          `json:"id"`
	Variant string          `json:"variant"`
	Steps   []setupCaseStep `json:"steps"`
}

func loadSetupCases(t *testing.T) []setupCase {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("runtime.Caller(0) failed")
	}
	path := filepath.Join(filepath.Dir(file), "..", "..", "tests", "fixtures", "abi-v1", "setup-cases.json")
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var doc struct {
		Cases []setupCase `json:"cases"`
	}
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatalf("%s: %v", path, err)
	}
	if len(doc.Cases) == 0 {
		t.Fatalf("%s: zero cases; a suite that ran nothing must not pass", path)
	}
	return doc.Cases
}

// setupStepOutcome compares one step's outcome with its expectation, and
// returns what differs, or "" when they agree.
func setupStepOutcome(want setupCaseExpect, err error) string {
	if want.OK {
		if err != nil {
			return fmt.Sprintf("want success, got %T: %v", err, err)
		}
		return ""
	}
	if err == nil {
		return fmt.Sprintf("want a %s error, got success", want.Class)
	}
	var matched bool
	switch want.Class {
	case "schema":
		var e *SchemaError
		matched = errors.As(err, &e)
	case "unsupported":
		var e *UnsupportedError
		matched = errors.As(err, &e)
	case "usage":
		var e *UsageError
		matched = errors.As(err, &e)
	case "internal":
		var e *InternalError
		matched = errors.As(err, &e)
	default:
		return fmt.Sprintf("the case names an error class this runner does not know: %q", want.Class)
	}
	if !matched {
		return fmt.Sprintf("want a %s error, got %T: %v", want.Class, err, err)
	}
	ce, ok := AsCallError(err)
	if !ok {
		return fmt.Sprintf("%T carries no call error fields", err)
	}
	if want.Status != "" && ce.Status.String() != want.Status {
		return fmt.Sprintf("status %s, want %s", ce.Status, want.Status)
	}
	if want.ChCode != nil && ce.ChCode != *want.ChCode {
		return fmt.Sprintf("ch_code %d, want %d", ce.ChCode, *want.ChCode)
	}
	if want.ChName != nil && ce.ChName != *want.ChName {
		return fmt.Sprintf("ch_name %q, want %q", ce.ChName, *want.ChName)
	}
	return ""
}

// TestSetupCases runs every shared setup case: one fresh image per case, no
// setup recorded at its start, and each step through the public API.
func TestSetupCases(t *testing.T) {
	stubDir(t) // skips loudly without the stubs
	for _, c := range loadSetupCases(t) {
		t.Run(c.ID, func(t *testing.T) {
			resetSetup(t)
			t.Setenv("CHTYPES_ALLOW_UNVERIFIED_LIBRARY", "1")
			image := stubFile(t, c.Variant)
			if len(c.Steps) == 0 {
				t.Fatal("a case with no steps")
			}
			for i, s := range c.Steps {
				var err error
				switch s.Op {
				case "setup":
					err = Setup(SetupOptions{Timezone: s.Timezone})
				case "open":
					_, err = OpenUnverified(image, true)
				default:
					t.Fatalf("step %d: an op this runner does not know: %q", i, s.Op)
				}
				if diff := setupStepOutcome(s.Expect, err); diff != "" {
					t.Fatalf("step %d (%s %q): %s", i, s.Op, s.Timezone, diff)
				}
			}
		})
	}
}
